1	#!/usr/bin/env node
2	// Claude Code PreToolUse guard, two duties:
3	//  - a Bash command that deletes a remote branch is blocked (the delete-push fails
4	//    in this environment, so it can never succeed);
5	//  - a file tool (Edit, Write, NotebookEdit) aimed at a path one of an active
6	//    pack's skills names under `force-load-on-file-edits-paths` is blocked until the
7	//    session has loaded that skill — so the skill is read before the first edit
8	//    exists, not after a Stop-time finding has sent the agent back over work done.
9	// Exit 2 blocks the tool call and feeds stderr back to the agent; the block is the
10	// one message the agent needs. Registered per-repo — see bootstrap.md.
11	import { existsSync, readFileSync } from 'node:fs';
12	import { dirname, isAbsolute, join, relative, resolve, sep } from 'node:path';
13	import { fileURLToPath } from 'node:url';
14	import { hooklog } from '../checks/helpers/hook-log.mjs';
15	import { parseEntries, skillLoads } from '../checks/helpers/session-transcript.mjs';
16	import { pathScopedSkills, missingSkillsFor } from '../pack_loader/path-scoped-skills.mjs';
17	import { settingsPath } from '../settings-file.mjs';
18	
19	// The file a tool is about to write, repo-relative with forward slashes — or null
20	// when the tool names no file or the file is outside the project (nothing here
21	// scopes a path the repo does not own).
22	function targetPath(payload, projectRoot) {
23	  const input = payload.tool_input ?? {};
24	  const raw = payload.tool_name === 'NotebookEdit' ? input.notebook_path : input.file_path;
25	  if (typeof raw !== 'string' || !raw) return null;
26	  const abs = isAbsolute(raw) ? raw : resolve(projectRoot, raw);
27	  const rel = relative(projectRoot, abs);
28	  if (!rel || rel.startsWith('..') || isAbsolute(rel)) return null;
29	  return rel.split(sep).join('/');
30	}
31	
32	async function activePacks(projectRoot) {
33	  // This module lives at <corpus>/engine/hooks/ — the same root the mount hook
34	  // resolves the registry from, so the canon runs it from its own tree.
35	  const corpusRoot = dirname(dirname(dirname(fileURLToPath(import.meta.url))));
36	  let declared = [];
37	  const configPath = settingsPath(projectRoot);
38	  if (existsSync(configPath)) {
39	    const raw = JSON.parse(readFileSync(configPath, 'utf8'));
40	    if (Array.isArray(raw.packs)) declared = raw.packs;
41	  }
