import { finding } from '../../../engine/checks/helpers/findings.mjs';
import { classificationLine, classesIn } from '../../../engine/checks/helpers/session-transcript.mjs';

// Sharpens comment-classification (which only checks a `Comment class:` line
// EXISTS) with the form RULES.md already demands: the class alone on its own
// line, any explanation on the next one. `classesIn()` — the same helper every
// classification-gated rule reads — matches every class token ANYWHERE on the
// line, so an explanation sharing that line declares whatever it happens to
// mention, not what the author meant to say.
//
// This asserts the FORM, not the author's intent, and it has to: a check that
// instead hunted for a class token following a negation word ("not", "never",
// "besides", …) stays silent on real replies that smuggle a class anyway —
//     Comment class: other — unrelated to any feature request      (declares feature)
//     Comment class: other, setting the feature question aside     (declares feature)
//     Comment class: correction | feature | process-change | other (declares all four,
//                                                          the menu pasted verbatim)
// The harm is a class token being PRESENT on the line, not negated, so only
// checking that the line's content IS the declaration — and nothing else —
// catches all three with no word list to keep current. A genuinely mixed
// comment stays legal and stays silent: it names each part it really is,
// positively, comma-separated, on that one line (`Comment class: correction,
// process-change`). Markdown emphasis around the bare declaration
// (`**Comment class: other**`) is tolerated, matching the leading decoration
// classificationLine() already allows.
//
// ADVISORY, deliberately, where the underlying defect is blocking-grade
// elsewhere: the transcript this rule reads is append-only, so by the time a
// malformed line is observable it cannot be retracted, and a blocking finding
// here could never converge — it would spend every Stop cycle on something no
// edit can fix. Its job is only to name the cause the moment it appears, so a
// session doesn't have to re-derive it from an unrelated downstream failure.

const CLASS = String.raw`(?:correction|feature|process[\s-]change|other)`;
// `|` is deliberately not a separator — it's how a menu is written out, so
// pasting the menu verbatim fails this pattern instead of reading as a
// four-class declaration.
const CONFORMING_RE = new RegExp(String.raw`^${CLASS}(?:\s*(?:,|&|\+|and)\s*${CLASS})*\.?$`, 'i');

function bareDeclaration(text) {
  return text.trim().replace(/^[*_]+|[*_]+$/g, '').trim();
}

const rule = {
  id: 'comment-classification-form',
  severity: 'advisory',
  description: 'The `Comment class:` line must carry the class alone — every class token on it is declared, however the line phrases them',
  doc: 'packs/basics/RULES.md',
  scope: 'work',
  why: 'classesIn() matches every class token anywhere on the classification line, so an explanation sharing that line declares whatever it happens to mention, not just what the author meant',

  run(work) {
    const turn = work.conversation().ownerTurns().last();
    if (!turn.exists) return [];
    const line = classificationLine(turn.reply());
    if (!line) return []; // no classification line at all — comment-classification's finding, not this one

    const declaration = bareDeclaration(line.slice(line.indexOf(':') + 1));
    if (CONFORMING_RE.test(declaration)) return [];

    const declared = [...classesIn(line)].sort();
    if (!declared.length) return []; // names no class at all — comment-classification's finding, not this one

    return [finding(rule, {
      file: '(conversation)',
      what: `the \`Comment class:\` line carries more than the class it means, so it is read as declaring ${declared.map((c) => `\`${c}\``).join(', ')}`,
      fix: 'write the class alone on its own line, and put any explanation on the NEXT line; a genuinely mixed comment names each part it really is, comma-separated, on that one line. The transcript is append-only, so a clean re-declaration further down does not override this one',
    })];
  },
};

export default rule;
=====NODE CHECK=====
import { finding } from '../../../engine/checks/helpers/findings.mjs';
import { workflowFiles } from '../../../engine/checks/helpers/github-workflows.mjs';

// WHY. Node's default test discovery skips dot-directories outright, so a
// `node --test` naming no path — or naming a path that has since moved,
// typo'd, or been renamed — finds nothing, reports success, and reads exactly
// like a passing suite. The failure mode is a green tick over zero assertions,
// which no human and no CI log inspection reliably catches.
//
// This is why the rule asserts the stronger property — the invocation's
// arguments must resolve to something that exists — rather than merely "an
// argument was passed". Watching the run go green is never the confirmation;
// a statically non-empty argument set is.
//
// SCOPE. The command surfaces a run can be spelled on: `package.json` scripts
// (the local invocation) and `.github/workflows/*.yml` (the CI step). A command
// carrying shell interpolation (`$…`, backticks) is not judged — its arguments
// are not knowable from the artifact, and a check that guesses cries wolf.

const SHARED_PREFIX = '.claudinite/shared/';

// A shell command's tokens, quotes stripped. Deliberately naive: the commands
// this rule reads are short literal invocations, and anything with substitution
// in it is skipped before we get here.
function tokenize(command) {
  return command.trim().split(/\s+/).filter(Boolean).map((t) => t.replace(/^['"]|['"]$/g, ''));
}

// Split a script body / run: line into individual commands on the shell's
// separators, so `npm ci && node --test` is judged as its two commands.
function commands(text) {
  return text.split(/\n|&&|\|\||[;|]/g);
}

// A glob token as a regex over '/'-separated repo paths: `**` crosses
// directories, `*` and `?` do not.
function globToRegExp(pattern) {
  let out = '';
  for (let i = 0; i < pattern.length; i += 1) {
    const c = pattern[i];
    if (c === '*') {
      if (pattern[i + 1] === '*') {
        // `**/` may match zero directories, so the following slash is optional.
        i += 1;
        if (pattern[i + 1] === '/') { i += 1; out += '(?:.*/)?'; } else out += '.*';
      } else out += '[^/]*';
    } else if (c === '?') out += '[^/]';
    else out += c.replace(/[.+^${}()|[\]\\]/g, '\\$&');
  }
  return new RegExp(`^${out}$`);
}

// Does this argument name at least one file that exists in the repo — as a
// glob, an exact path, or a directory holding files?
export function resolvesToFiles(arg, paths) {
  if (!arg) return false;
  if (/[*?[\]]/.test(arg)) {
    const re = globToRegExp(arg);
    return paths.some((p) => re.test(p));
  }
  const clean = arg.replace(/\/+$/, '');
  return paths.some((p) => p === clean || p.startsWith(`${clean}/`));
}

// The invocations of `node --test` in one command string, and whether each
// one's arguments resolve. Exported for the fixture.
export function judgeCommand(command, paths) {
  if (/[$`]/.test(command)) return null; // interpolated — not knowable from the artifact
  const tokens = tokenize(command);
  const nodeAt = tokens.findIndex((t) => t === 'node' || t.endsWith('/node'));
  if (nodeAt < 0) return null;
  const args = tokens.slice(nodeAt + 1);
  if (!args.includes('--test')) return null;
  // Flags are skipped; every other token is a candidate path. A flag's separate
  // value can only ever make the rule quieter, never noisier.
  const positional = args.filter((t) => !t.startsWith('-'));
  return { ok: positional.some((a) => resolvesToFiles(a, paths)) };
}

const rule = {
  id: 'node/node-test-discovery',
  severity: 'blocking',
  description: 'A `node --test` invocation must name test paths that exist — default discovery skips dot-directories',
  doc: 'packs/node/RULES.md',
  why: "Node's test discovery ignores dot-directories, so an invocation that names no existing path (or a stale glob) runs zero tests and exits green, which is indistinguishable from a passing suite",

  run(ctx) {
    // Tracked ∪ scanned: `ctx.tracked` is the whole tree in either mode, and
    // `ctx.files` adds the not-yet-committed ones — a test file added in the
    // same change as the step that runs it must resolve, or the rule fires on
    // the very commit that fixes it.
    const paths = [...new Set([...ctx.tracked, ...(ctx.files || [])])]
      .filter((f) => !f.startsWith(SHARED_PREFIX));
    const out = [];

    const report = (file, line, command) => out.push(finding(rule, {
      file,
      line,
      what: `\`${command.trim()}\` names no test path that exists in the tree, so it discovers nothing and exits green`,
      fix: "pass an explicit path or glob for the tests, e.g. `node --test '.claudinite/local/packs/**/*.test.mjs'`, and confirm the run's test count is non-zero",
    }));

    const pkg = ctx.read('package.json');
    if (pkg !== null) {
      let scripts = {};
      try { scripts = JSON.parse(pkg).scripts || {}; } catch { scripts = {}; }
      const lines = pkg.split('\n');
      for (const [name, body] of Object.entries(scripts)) {
        if (typeof body !== 'string') continue;
        for (const command of commands(body)) {
          const verdict = judgeCommand(command, paths);
          if (verdict && !verdict.ok) {
            const at = lines.findIndex((l) => l.includes(`"${name}":`));
            report('package.json', at < 0 ? null : at + 1, command);
          }
        }
      }
    }

    for (const wf of workflowFiles(ctx)) {
      const text = ctx.read(wf);
      if (text === null) continue;
      const lines = text.split('\n');
      for (let i = 0; i < lines.length; i += 1) {
        for (const command of commands(lines[i])) {
          const verdict = judgeCommand(command, paths);
          if (verdict && !verdict.ok) report(wf, i + 1, command);
        }
      }
    }

    return out;
  },
};

export default rule;

